// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint128 amount, uint64 ts, uint256 blockNum) public {
        vm.assume(ts > 1);
        vm.assume(blockNum >= 1);
        address actor = address(0xABCD);
        vm.deal(actor, amount);
        vm.warp(ts);
        vm.roll(blockNum);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        // General rule: a successful fallback call implies exactly 10 ether was sent.
        assertTrue(!ok || amount == 10 ether, "success must imply msg.value == 10 ether");
    }
}
